from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    # expired, treat as absent
                    del cache[key]
            if key in cache:
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    # evict LRU, but first need to consider only if key not already counted
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache:
                v, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(v)
            else:
                results.append(-1)
    return results

